/**
 * Counter-composition for the AI: given the enemy army it has actually seen (ai-intel.ts), how good is each unit
 * it could build? Measured cost-equal battle results (ai-matchups.ts, regenerated by tools/selfplay/balance.ts)
 * weighted by the value share of each enemy unit type; pairs the table lacks (new units, ships) fall back to a
 * Lanchester estimate from the rules themselves (weapon damage, rate of fire, warhead-vs-armour verses, hit
 * points, cost, air / naval reach):
 *
 *   offence  = enemy value it destroys per second per $ spent
 *   exposure = own value the enemy destroys per second per $ spent
 *   exchange = offence / exposure
 *
 * Rocket soldiers come out on top against armour, grenadiers / flamers / machine guns against infantry, anything
 * with anti-air (rockets, mammoth tusks, destroyers) against aircraft, and so on.
 */
import { ARMOR_INDEX, UNITS, WARHEADS, WEAPONS, RA_TICKS_PER_SECOND, type UnitTypeDef, type WeaponDef } from '../data/rules';
import type { AIIntel } from './ai-intel';
import { TICK_HZ } from './types';
import { MATCHUPS } from './ai-matchups';

/** Damage per second of `a`'s best weapon against unit type `t` (0 if it can't engage it). */
function dps(a: UnitTypeDef, t: UnitTypeDef): number {
  let best = 0;
  for (const id of [a.primary, a.secondary]) {
    if (!id) continue;
    const w = WEAPONS[id];
    if (!w || !canEngage(w, a, t)) continue;
    const mult = WARHEADS[w.warhead]?.verses[ARMOR_INDEX[t.armor]] ?? 0;
    const shots = w.burst * (a.twinShot && id === a.primary ? 2 : 1);
    const v = (w.damage * mult * shots) / Math.max(1, w.rof / RA_TICKS_PER_SECOND);
    if (v > best) best = v;
  }
  return best;
}

function canEngage(w: WeaponDef, a: UnitTypeDef, t: UnitTypeDef): boolean {
  if (w.damage <= 0) return false;
  const air = t.kind === 'aircraft';
  if (air ? !w.antiAir : !w.antiGround) return false;
  if (w.warhead === 'Organic') return t.kind === 'infantry';
  if (w.projectile === 'torpedo' || w.projectile === 'depthcharge') return t.kind === 'naval' && (w.projectile === 'torpedo' || !!t.cloakable);
  // ground forces rarely get to shoot at ships, and ships only reach the coast
  if (t.kind === 'naval' && a.kind !== 'naval' && a.kind !== 'aircraft') return w.range >= 6;
  return true;
}

const cache = new Map<string, number>();
function dpsCached(a: string, t: string): number {
  const k = a + '>' + t;
  let v = cache.get(k);
  if (v === undefined) {
    const A = UNITS[a], T = UNITS[t];
    v = A && T ? dps(A, T) : 0;
    cache.set(k, v);
  }
  return v;
}

/**
 * Enemy unit types seen recently with their value (harvesters and MCVs excluded). With little seen yet, a prior
 * fills in: the army the enemy's faction typically fields (a commander knows whom he is fighting, not what he
 * brought), fading out as real sightings accumulate.
 */
export function enemyComposition(intel: AIIntel, sec = 150, prior?: Map<string, number>): { types: Map<string, number>; total: number } {
  const seen = seenComposition(intel, sec);
  if (!prior || seen.total >= PRIOR_FADE) return seen;
  const ptotal = [...prior.values()].reduce((a, b) => a + b, 0);
  if (ptotal <= 0) return seen;
  const scale = (PRIOR_FADE - seen.total) / ptotal;
  const types = new Map(seen.types);
  for (const [t, v] of prior) types.set(t, (types.get(t) ?? 0) + v * scale);
  return { types, total: PRIOR_FADE };
}

/** Sightings needed before the prior no longer counts. */
const PRIOR_FADE = 4000;

function seenComposition(intel: AIIntel, sec: number): { types: Map<string, number>; total: number } {
  const types = new Map<string, number>();
  let total = 0;
  const since = intel.world.tick - sec * TICK_HZ;
  for (const s of intel.units.values()) {
    if (s.seen < since || s.type === 'harv' || s.type === 'mcv' || !UNITS[s.type]) continue;
    const u = UNITS[s.type];
    if (!u.primary && !u.secondary) continue;
    types.set(s.type, (types.get(s.type) ?? 0) + s.cost);
    total += s.cost;
  }
  return { types, total };
}

/**
 * log2 of the exchange ratio of unit type `a` against `b` in a cost-equal fight: the measured table
 * (ai-matchups.ts, from tools/selfplay/balance.ts) when it has the pair, else a Lanchester estimate from the rules
 * (damage per second x value per hit point, both ways). 0 = even, +1 = trades twice its value.
 */
export function matchup(a: string, b: string): number {
  const m = MATCHUPS[a]?.[b];
  if (m !== undefined) return m;
  if (MATCHUPS[a] && MATCHUPS[b]) return 0; // measured: neither can hurt the other
  const A = UNITS[a], B = UNITS[b];
  if (!A || !B) return 0;
  const offence = (dpsCached(a, b) * (B.cost / B.strength)) / A.cost;
  const exposure = (dpsCached(b, a) * (A.cost / A.strength)) / B.cost;
  if (offence <= 0 && exposure <= 0) return 0;
  return Math.max(-6, Math.min(6, Math.log2((offence + 1e-7) / (exposure + 1e-7))));
}

/** Expected log2 exchange of unit type `id` against an enemy composition (value per type). Higher is better. */
export function fitness(id: string, comp: Map<string, number>, total: number): number {
  if (total <= 0) return 0;
  let f = 0;
  for (const [t, v] of comp) f += (v / total) * matchup(id, t);
  return f;
}

/** How well the best of these unit types would fare against the enemy army seen (log2 exchange), or null if too little is known. */
export function bestFitness(ids: string[], intel: AIIntel, minSeen = 1200, prior?: Map<string, number>): number | null {
  const { types, total } = enemyComposition(intel, 150, prior);
  if (total < minSeen || !ids.length) return null;
  let best = -Infinity;
  for (const id of ids) best = Math.max(best, fitness(id, types, total));
  return best;
}

/**
 * Weight multipliers for a unit mix: 2^(k * (fitness - mean)), clamped. `k` = how strongly to follow the estimate
 * (0 = ignore it). Returns 1 for everything when too little of the enemy has been seen.
 */
export function counterWeights(mix: string[], intel: AIIntel, k: number, minSeen = 1200, prior?: Map<string, number>): Map<string, number> {
  const out = new Map<string, number>();
  const { types, total } = enemyComposition(intel, 150, prior);
  if (k <= 0 || total < minSeen || !mix.length) {
    for (const id of mix) out.set(id, 1);
    return out;
  }
  const f = mix.map((id) => fitness(id, types, total));
  const mean = f.reduce((s, x) => s + x, 0) / f.length;
  // more information, more confidence
  const conf = Math.min(1, total / 6000);
  mix.forEach((id, i) => out.set(id, Math.max(0.2, Math.min(4, Math.pow(2, (f[i] - mean) * k * conf)))));
  return out;
}
